+      border-radius: var(--radius);
+      box-shadow: var(--shadow);
+      padding: clamp(24px, 5vw, 36px);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(1.6rem, 3vw, 2.1rem);
+      line-height: 1.15;
+      letter-spacing: -0.03em;
+    }
+
+    .lead {
+      margin: 0 0 28px;
+      color: var(--muted);
+      max-width: 42ch;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 18px;
+      border: 1px solid var(--border);
+      border-radius: 16px;
+      background: #f8fbff;
+    }
+
+    .checkbox-row {
+      display: flex;
+      gap: 12px;
+      align-items: flex-start;
+    }
+
+    input[type="checkbox"] {
+      width: 20px;
+      height: 20px;
+      margin: 2px 0 0;
+      accent-color: var(--primary);
+      flex: 0 0 auto;
+    }
+
+    label {
+      font-weight: 600;
+      cursor: pointer;
+    }
+
+    .helper {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .required {
+      color: var(--primary-dark);
+      font-weight: 700;
+    }
+
+    .actions {
+      margin-top: 22px;
+      display: flex;
+      align-items: center;
+      gap: 14px;
+      flex-wrap: wrap;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      background: linear-gradient(180deg, var(--primary), var(--primary-dark));
+      color: #fff;
+      padding: 12px 18px;
+      font: inherit;
+      font-weight: 700;
+      box-shadow: 0 10px 22px rgba(37, 99, 235, 0.24);
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.02);
+    }
+
+    button:focus-visible,
+    input:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5em;
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .status[data-state="success"] {
+      color: #166534;
+    }
+
+    .status[data-state="error"] {
+      color: #b91c1c;
+    }
+
+    @media (max-width: 480px) {
+      body {
+        padding: 16px;
+      }
+
+      .card {
+        padding: 20px;
+      }
+
+      .checkbox-row {
+        gap: 10px;
+      }
+    }
+
+    @media (forced-colors: active) {
+      :root {
+        --bg: Canvas;
+        --surface: Canvas;
+        --text: CanvasText;
+        --muted: CanvasText;
+        --border: ButtonBorder;
+        --primary: ButtonText;
+        --primary-dark: ButtonText;
+        --focus: ButtonText;
+      }
+
+      .card,
+      .form-field,
+      button {
+        border: 1px solid ButtonBorder;
+      }
+
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+        box-shadow: none;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main">Skip to main content</a>
+
+  <main id="main">
+    <section class="card" aria-labelledby="page-title">
+      <h1 id="page-title">Terms of Use Consent</h1>
+      <p class="lead">Please confirm that you agree to the terms before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input id="terms-consent" name="termsConsent" type="checkbox" required aria-describedby="consent-help consent-status" />
+            <label for="terms-consent">
+              I agree to the terms of use <span class="required" aria-hidden="true">*</span>
+            </label>
+          </div>
+          <p class="helper" id="consent-help">You must check this box to submit the form.</p>
+        </div>
+
+        <div class="actions">
+          <button type="submit">Submit</button>
+          <p class="status" id="consent-status" aria-live="polite"></p>
+        </div>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('terms-consent');
+    const status = document.getElementById('consent-status');
+
+    form.addEventListener('submit', (event) => {
+      if (!checkbox.checked) {
+        event.preventDefault();
+        checkbox.setCustomValidity('Please agree to the terms of use before submitting.');
+        checkbox.reportValidity();
+        status.textContent = 'Please agree to the terms of use to continue.';
+        status.dataset.state = 'error';
+        return;
+      }
+
+      checkbox.setCustomValidity('');
+      event.preventDefault();
+      status.textContent = 'Thanks — your consent has been recorded.';
+      status.dataset.state = 'success';
+    });
+
+    checkbox.addEventListener('change', () => {
+      if (checkbox.checked) {
+        checkbox.setCustomValidity('');
+        status.textContent = '';
+        status.removeAttribute('data-state');
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
